package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.articles.JdbcEntityAnalysisState;
import com.lianxibu.site.service.articles.EntityAnalysisStateService;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;

/** Actual registered source/application/full final/whole day permission and native allocation; sender is fictional. */
class CatalogDayAnalysisGenerationTest {
    boolean mysql(){return false;}
    CatalogDayAnalysisEligibilityTest outer(){return new CatalogDayAnalysisEligibilityTest(){@Override boolean mysql(){return CatalogDayAnalysisGenerationTest.this.mysql();}};}
    CatalogDayAnalysisGenerationService service(CatalogDayAnalysisEligibilityTest outer,CatalogDayFullNativeIntegrationTest.Fixture f,Clock clock){return service(outer,f,outer.eligibility(f),clock);}
    CatalogDayAnalysisGenerationService service(CatalogDayAnalysisEligibilityTest outer,CatalogDayFullNativeIntegrationTest.Fixture f,CatalogDayAnalysisEligibilityService eligibility,Clock clock){return new CatalogDayAnalysisGenerationService(eligibility,new CatalogDayAnalysisReservationLedger(new JdbcCatalogDayAnalysisReservations(f.f.source),f.f.category),new EntityAnalysisStateService(new JdbcEntityAnalysisState(f.f.source)),new JdbcJobRecords(f.f.source),f.f.writes,clock,f.f.category);}
    @Test void FourCategoriesActualNewGenerationIntentAndPermanentReceiptCommitExactlyOnce(){
        for(String category:List.of("agent","skill","workflow","model")){
            var outer=outer();var f=outer.new NewFixture();f.terminal(category);f.completeSource();var eligible=outer.eligibility(f);var captured=eligible.capture(outer.day);var selected=captured.selected().getFirst();long before=selected.header().revision();int jobs=f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);var coordinator=service(outer,f,eligible,Clock.fixed(outer.completed.plusSeconds(90),ZoneOffset.UTC));var stored=coordinator.reserve(outer.day,selected.entity().entityId());assertEquals(1,stored.generation());assertEquals(before,stored.entityRevisionBefore());assertEquals(before+1,stored.entityRevisionAfter());assertEquals("queued",f.f.jdbc.queryForObject("SELECT analysis_state FROM analyzed_entities",String.class));assertEquals(1,f.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(before+1,f.f.jdbc.queryForObject("SELECT revision FROM analyzed_entities",Long.class));assertEquals(jobs+2,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(0,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE intent_id=?",Integer.class,stored.intentId()));assertEquals(stored.json(),coordinator.reserve(outer.day,stored.entityId()).json());assertEquals(jobs+2,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(2,f.f.sends);
        }
    }
    @Test void ActualPositiveAliasMembersJoinExistingIntentWithoutAnotherGeneration(){
        var outer=outer();var aliases=new CatalogDayAliasEvidenceTest(){@Override boolean mysql(){return CatalogDayAnalysisGenerationTest.this.mysql();}};var f=aliases.new AliasFixture();f.terminal("agent");f.completeSource();var eligible=outer.eligibility(f);var original=eligible.capture(outer.day);var selected=original.selected().getFirst();int jobs=f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);var stored=service(outer,f,eligible,Clock.fixed(outer.completed.plusSeconds(90),ZoneOffset.UTC)).reserve(outer.day,selected.entity().entityId());assertEquals(selected.intentId(),stored.intentId());assertEquals(2,stored.generation());assertEquals(selected.header().revision(),stored.entityRevisionAfter());assertEquals(2,stored.members().size());assertEquals(2,original.selected().getFirst().entity().members().stream().map(CatalogDayEntityEvidenceService.Evidence::identityKey).distinct().count());assertEquals(jobs+1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(2,f.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_version_judgment'",Integer.class));assertEquals(2,f.f.sends);
    }
    @Test void PermanentReceiptReplayPrecedesCurrentQualificationClocksAndRemovedTables(){
        var outer=outer();var f=outer.new NewFixture();f.terminal("model");f.completeSource();var original=outer.eligibility(f).capture(outer.day);String entity=original.selected().getFirst().entity().entityId();var stored=service(outer,f,Clock.fixed(outer.completed.plusSeconds(90),ZoneOffset.UTC)).reserve(outer.day,entity);int jobs=f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);f.f.jdbc.execute("DROP TABLE sources");f.f.jdbc.execute("DROP TABLE source_run_items");f.f.jdbc.execute("DROP TABLE analyzed_entities");var qualification=mock(CatalogDayAnalysisEligibilityService.class);var clock=mock(Clock.class);assertEquals(stored.json(),service(outer,f,qualification,clock).reserve(outer.day,entity).json());verifyNoInteractions(qualification,clock);assertEquals(jobs,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(2,f.f.sends);
    }
    @Test void ReceiptFailureRollsBackNewGenerationAndNewIntentThenNativeAckLossRecovers(){
        var outer=outer();var f=outer.new NewFixture();f.terminal("workflow");f.completeSource();var eligible=outer.eligibility(f);var captured=eligible.capture(outer.day);var selected=captured.selected().getFirst();int jobs=f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);var coordinator=service(outer,f,eligible,Clock.fixed(outer.completed.plusSeconds(90),ZoneOffset.UTC));f.f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_analysis_reservation_failure CHECK(target_type IS NULL OR target_type<>'catalog_day_analysis')");assertThrows(RuntimeException.class,()->coordinator.reserve(outer.day,selected.entity().entityId()));assertEquals(0,f.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals("pending",f.f.jdbc.queryForObject("SELECT analysis_state FROM analyzed_entities",String.class));assertEquals(selected.header().revision(),f.f.jdbc.queryForObject("SELECT revision FROM analyzed_entities",Long.class));assertEquals(jobs,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));f.f.jdbc.execute(mysql()?"ALTER TABLE jobs DROP CHECK fictional_analysis_reservation_failure":"ALTER TABLE jobs DROP CONSTRAINT fictional_analysis_reservation_failure");f.f.tx.ackLost=true;var stored=coordinator.reserve(outer.day,selected.entity().entityId());assertEquals(1,stored.generation());assertEquals(jobs+2,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(stored.json(),service(outer,f,mock(CatalogDayAnalysisEligibilityService.class),mock(Clock.class)).reserve(outer.day,stored.entityId()).json());assertEquals(2,f.f.sends);
    }
    @Test void FreshCasAndOriginalBodyDamageRejectBeforeAllocationAndReceiptCorruptionNeverReplaces(){
        var outer=outer();var f=outer.new NewFixture();f.terminal("skill");f.completeSource();var actual=outer.eligibility(f);var captured=actual.capture(outer.day);var selected=captured.selected().getFirst();var spied=spy(actual);doReturn(captured).when(spied).capture(outer.day);var coordinator=service(outer,f,spied,Clock.fixed(outer.completed.plusSeconds(90),ZoneOffset.UTC));int jobs=f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);f.f.jdbc.update("UPDATE analyzed_entities SET revision=revision+1");assertThrows(RuntimeException.class,()->coordinator.reserve(outer.day,selected.entity().entityId()));assertEquals(0,f.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(jobs,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));f.f.jdbc.update("UPDATE analyzed_entities SET revision=revision-1");f.f.jdbc.update("UPDATE source_run_items SET evidence_hash=?",new byte[32]);assertThrows(RuntimeException.class,()->coordinator.reserve(outer.day,selected.entity().entityId()));assertEquals(jobs,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));
        var recovered=outer.new NewFixture();recovered.terminal("skill");recovered.completeSource();var ready=outer.eligibility(recovered).capture(outer.day);String entity=ready.selected().getFirst().entity().entityId();var service=service(outer,recovered,Clock.fixed(outer.completed.plusSeconds(90),ZoneOffset.UTC));var stored=service.reserve(outer.day,entity);int after=recovered.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);recovered.f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE id=?",new byte[32],JdbcCatalogDayAnalysisReservations.id(stored.reservationKey()));assertThrows(RuntimeException.class,()->service.reserve(outer.day,entity));assertEquals(after,recovered.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(1,recovered.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));
    }
    @Test void UnclosedAndDeclinedOriginalDaysCannotAllocate(){
        var outer=outer();var f=outer.new NewFixture();f.terminal("agent");String entity="fictional-uncreated-entity";assertThrows(RuntimeException.class,()->service(outer,f,Clock.fixed(outer.completed.plusSeconds(90),ZoneOffset.UTC)).reserve(outer.day,entity));assertEquals(0,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_day_analysis'",Integer.class));
        var declined=outer.new Fixture();declined.terminal("model");var payload=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(declined.raw).get("payload");for(var member:payload.get("items"))((tools.jackson.databind.node.ObjectNode)member).put("reanalyze_recommended",false);declined.raw=ResultApplicationService.providerEnvelope(declined.application.input(),JdbcFrozenInputs.canonical(payload));declined.completeSource();assertThrows(RuntimeException.class,()->service(outer,declined,Clock.fixed(outer.completed.plusSeconds(90),ZoneOffset.UTC)).reserve(outer.day,"fictional-entity"));assertEquals(1,declined.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(0,declined.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_day_analysis'",Integer.class));
    }
    @Test void TwoActualCallersContendOnOneNativeGenerationAndReturnOneOriginal() throws Exception {
        var outer=outer();var f=outer.new NewFixture();f.terminal("agent");f.completeSource();var actual=outer.eligibility(f);var captured=actual.capture(outer.day);String entity=captured.selected().getFirst().entity().entityId();var synchronizedPreparation=spy(actual);var barrier=new CyclicBarrier(2);doAnswer(call->{barrier.await(5,TimeUnit.SECONDS);return captured;}).when(synchronizedPreparation).capture(outer.day);var coordinator=service(outer,f,synchronizedPreparation,Clock.fixed(outer.completed.plusSeconds(90),ZoneOffset.UTC));int jobs=f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);try(var threads=Executors.newFixedThreadPool(2)){var first=threads.submit(()->coordinator.reserve(outer.day,entity));var second=threads.submit(()->coordinator.reserve(outer.day,entity));assertEquals(first.get(10,TimeUnit.SECONDS).json(),second.get(10,TimeUnit.SECONDS).json());}assertEquals(jobs+2,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(1,f.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(2,f.f.sends);
    }
    @Test void MandatoryClosedCategoryConsumerConstructionDoesNoIo(){var eligibility=mock(CatalogDayAnalysisEligibilityService.class);var ledger=mock(CatalogDayAnalysisReservationLedger.class);var entities=mock(EntityAnalysisStateService.class);var records=mock(JdbcJobRecords.class);var writes=mock(SharedWriteExecutor.class);var clock=mock(Clock.class);for(String category:List.of("agent","skill","workflow","model"))assertNotNull(new CatalogDayAnalysisGenerationService(eligibility,ledger,entities,records,writes,clock,category));verifyNoInteractions(eligibility,ledger,entities,records,writes,clock);assertThrows(RuntimeException.class,()->new CatalogDayAnalysisGenerationService(eligibility,ledger,entities,records,writes,clock,"news_tech"));assertThrows(RuntimeException.class,()->new CatalogDayAnalysisGenerationService(null,ledger,entities,records,writes,clock,"agent"));}
}
